-- name: CreateRefreshToken :exec
INSERT INTO refresh_tokens (token_hash, family_id, user_id, expires_at, created_at)
VALUES ($1, $2, $3, $4, $5);

-- name: ConsumeRefreshToken :one
-- Single use: marks an unused, unrevoked token used, atomically.
UPDATE refresh_tokens SET used_at = sqlc.arg('now')::timestamptz
WHERE token_hash = sqlc.arg('token_hash') AND used_at IS NULL AND revoked_at IS NULL
RETURNING family_id, user_id, expires_at;

-- name: GetRefreshToken :one
SELECT * FROM refresh_tokens WHERE token_hash = $1;

-- name: RevokeRefreshFamily :exec
UPDATE refresh_tokens SET revoked_at = sqlc.arg('now')::timestamptz
WHERE family_id = sqlc.arg('family_id') AND revoked_at IS NULL;

-- name: RevokeUserRefreshTokens :exec
UPDATE refresh_tokens SET revoked_at = sqlc.arg('now')::timestamptz
WHERE user_id = sqlc.arg('user_id') AND revoked_at IS NULL;
